import { createMemo, For, Show, splitProps, type Component, type JSX, type ParentComponent } from "solid-js";

import { L10n } from "#core/ui-next/components/l10n.jsx";
import { Tooltip, TooltipBaseProps } from "#core/ui-next/components/tooltip.jsx";

import { AdvisorRecommendations } from "#base/ui/tutorial/advisor-utilities.js";
import { AdvisorRecommendationPill, PillText } from "#base/ui-next/components/pills.jsx";
import type { ChooserDepthInfo, UnlockDisplayData } from "#base/ui-next/screens/choosers/helpers.js";

interface TechCivicNode {
	/** Display name for the node (already includes mastery numeral if applicable). */
	name: string;
	/** Unlocks organized by depth/mastery tier. */
	unlocksByDepth?: ChooserDepthInfo[];
	/** Cost to research this node. */
	cost?: number;
	/** Advisor recommendations for this node. */
	recommendations?: AdvisorRecommendations[];
	/** The current depth index being researched (0-based). Used to show only the current tier's unlocks. */
	currentDepthIndex?: number;
}

export interface TechCivicTooltipProps extends TooltipBaseProps {
	/** Node data for the tooltip contents */
	node: TechCivicNode;
	/** Whether the node is a civic (culture) node; toggles the cost icon */
	isCulture?: boolean;
}

/** Returns the player id that built the given wonder, or null if none. */
function getWonderPlayerId(wonderType: string | number): number | null {
	const wonderInfo = GameInfo.Wonders.lookup(wonderType);
	if (wonderInfo?.MaxWorldInstances === 1) {
		const players = Players.getEverAlive();
		for (const player of players) {
			const playerConstructibles = player?.Constructibles;
			if (!playerConstructibles?.getWonders) continue;
			const wonders = playerConstructibles.getWonders(player.id);
			for (const w of wonders) {
				const constructible = Constructibles.getByComponentID?.(w);
				if (constructible?.type === wonderInfo.$hash && constructible?.complete) {
					return player.id;
				}
			}
		}
	}
	return null;
}

const HorizontalDivider: Component<JSX.HTMLAttributes<HTMLDivElement>> = (props) => {
	return (
		<div
			class={`w-full h-px my-2 ${props.class ?? ""}`}
			style={{
				background: "linear-gradient(90deg, rgba(77, 83, 102, 0.70) 0%, rgba(77, 83, 102, 0.00) 100%)",
			}}
			{...props}
		/>
	);
};

interface UnlockItemProps extends JSX.HTMLAttributes<HTMLDivElement> {
	unlock: UnlockDisplayData;
}

/**
 * Renders a single unlock item in the tooltip with structured data.
 * Displays name, tags, yields, adjacencies, and descriptions using L10n components.
 */
const UnlockItem: ParentComponent<UnlockItemProps> = (props) => {
	const [local, other] = splitProps(props, ["unlock"]);

	const wonderBuiltByText = createMemo(() => {
		if (!local.unlock || local.unlock.kind !== "KIND_CONSTRUCTIBLE") return null;

		const constructible = GameInfo.Constructibles.lookup?.(local.unlock.type);
		if (constructible?.ConstructibleClass === "WONDER") {
			const owningPlayerId = getWonderPlayerId(local.unlock.type);
			if (owningPlayerId != null) {
				const you = GameContext?.localPlayerID;
				return owningPlayerId === you ? "LOC_UI_TREE_WONDER_BUILT_BY_YOU" : "LOC_UI_TREE_WONDER_BUILT_BY_OTHER";
			}
		}
		return null;
	});

	const descData = createMemo(() => local.unlock.descriptionData);
	const hasYields = createMemo(() => descData().yields.length > 0);
	const hasAdjacencies = createMemo(() => descData().adjacencies.length > 0);
	const hasDescriptions = createMemo(() => descData().descriptionLines.length > 0);

	return (
		<div
			{...other}
			class={`flex flex-row img-base-ticket-bg p-2 ${other.class ?? ""}`}
		>
			<img
				class="size-11\.5 self-center"
				src={local.unlock.icon}
			/>
			<div
				class="w-px min-h-11\.5 mx-2"
				style={{ "background-color": "rgba(217, 217, 217, .3)" }}
			/>
			<div class="flex flex-col flex-auto justify-center">
				{/* Name */}
				<Show when={local.unlock.nameKey}>
					<L10n.Stylize
						class="font-title text-secondary uppercase"
						text={local.unlock.nameKey}
					/>
					<HorizontalDivider />
				</Show>

				{/* Wonder built status */}
				<Show when={wonderBuiltByText()}>
					{(text) => (
						<L10n.Stylize
							class="text-secondary text-uppercase text-sm font-body font-bold tracking-25 flex flex-auto"
							text={text()}
						/>
					)}
				</Show>

				{/* Yields */}
				<Show when={hasYields()}>
					<div class="flex flex-col mb-1">
						<For each={descData().yields}>
							{(yieldChange) => (
								<>
									<div class="flex flex-row justify-between items-center text-sm leading-normal">
										<L10n.Stylize
											class="text-accent-4"
											text={`LOC_${yieldChange.yieldType}_NAME`}
										/>

										<L10n.Stylize
											class="mr-2"
											text="LOC_UI_POS_YIELD_ICON_ONLY"
											args={[yieldChange.amount, yieldChange.yieldType]}
										/>
									</div>

									<HorizontalDivider />
								</>
							)}
						</For>
					</div>
				</Show>

				{/* Adjacencies */}
				<Show when={hasAdjacencies()}>
					<div class="mb-1">
						<For each={descData().adjacencies}>
							{(group, index) => (
								<div>
									<L10n.Stylize
										class={`block ${index() > 0 ? "mt-1" : ""} ${group.listMarkup ? "mb-1" : ""}`}
										text={group.textKey}
										args={group.args}
									/>
									<Show when={group.listMarkup}>
										{(listText) => (
											<L10n.Stylize
												class="ml-4"
												text={listText() ?? ""}
											/>
										)}
									</Show>
								</div>
							)}
						</For>
					</div>
				</Show>

				{/* Description lines */}
				<Show when={hasDescriptions()}>
					<For each={descData().descriptionLines}>
						{(line, index) => (
							<L10n.Stylize
								class={`${index() > 0 ? "mt-1" : ""}`}
								text={line.text}
							/>
						)}
					</For>
				</Show>
			</div>
		</div>
	);
};

const StateText: Component<{ depth: ChooserDepthInfo; class?: string }> = (props) => {
	const stateText = createMemo(() => {
		if (props.depth.isCompleted) return "LOC_UI_COMPLETED_TREE";
		if (props.depth.isCurrent) return "LOC_UI_RESEARCHING_TREE";
		if (props.depth.isLocked) return "LOC_UI_LOCKED_TREE";
		return "";
	});
	return (
		<Show when={props.depth.isCompleted || props.depth.isCurrent || props.depth.isLocked}>
			<div class={`flex text-accent-3 text-xs font-body tracking-100 ${props.class ?? ""}`}>
				<L10n.Compose text={stateText()} />
			</div>
		</Show>
	);
};

export const TechCivicTooltip: ParentComponent<TechCivicTooltipProps> = (props) => {
	const [local, other] = splitProps(props, ["node", "isCulture", "children", "class"]);
	const costIcon = createMemo(() => (local.isCulture ? "[icon:YIELD_CULTURE]" : "[icon:YIELD_SCIENCE]"));
	const costAmount = createMemo(() => (local.node.cost ?? "").toString());

	// Get the current depth being researched (only show unlocks for this tier)
	const currentDepth = createMemo(() => {
		const depths = local.node.unlocksByDepth ?? [];
		const depthIndex = local.node.currentDepthIndex ?? 0;
		return depths[depthIndex];
	});

	return (
		<Tooltip
			offset={50}
			{...other}
		>
			<Tooltip.Trigger>{local.children}</Tooltip.Trigger>
			<Tooltip.Content class={`tech-civic-tooltip w-128 ${local.class ?? ""}`}>
				<Tooltip.Frame>
					<div class="flex flex-col justify-center items-center">
						<div class="text-secondary text-sm font-title uppercase tracking-100">{local.node.name}</div>
						<Show when={currentDepth()}>
							{(depth) => (
								<StateText
									depth={depth()}
									class="mb-2"
								/>
							)}
						</Show>
					</div>

					<Show when={currentDepth()}>
						{(depth) => (
							<div class="flex flex-col">
								<For each={depth().unlocks}>
									{(u, j) => (
										<UnlockItem
											class={j() != depth().unlocks.length - 1 ? "mb-2" : ""}
											unlock={u}
										/>
									)}
								</For>
							</div>
						)}
					</Show>

					<div class="flex flex-row flex-wrap items-center justify-center mt-2">
						<For each={local.node.recommendations ?? []}>
							{(rec, index) => (
								<AdvisorRecommendationPill
									textOverride="LOC_UI_RECOMMENDATION_DEFAULT"
									recommendation={rec}
									class="mt-2"
									classList={{
										"ml-2": index() > 0,
									}}
								/>
							)}
						</For>
						<PillText
							class="mt-2"
							classList={{
								"ml-2": local.node.recommendations && local.node.recommendations.length > 0,
							}}
							text="LOC_CARD_COST"
							args={[`${costAmount()}${costIcon()}`]}
						/>
					</div>
				</Tooltip.Frame>
			</Tooltip.Content>
		</Tooltip>
	);
};
